<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ValueObject\ConsentPurposeDescriptionVO;

trait ConsentPurposeDescriptionAttributeHolder
{
    protected ConsentPurposeDescriptionVO|string|null $description = null;
    protected bool $descriptionAssigned = false;

    public function getDescriptionOrCurrent(ConsentPurposeDescriptionVO $description): ConsentPurposeDescriptionVO
    {
        if ($this->descriptionAssigned) {
            \assert(null !== $this->description);
            return ConsentPurposeDescriptionVO::from($this->description);
        } else {
            return $description;
        }
    }
    public function descriptionTryBuildInitial(ConstraintFailList $error): ?ConsentPurposeDescriptionVO
    {
        return  ConsentPurposeDescriptionVO::tryFrom($this->descriptionAssigned ? $this->description : null, $error);
    }
    public function description(ConsentPurposeDescriptionVO|string $description): static
    {
        $this->description = $description;
        $this->descriptionAssigned = true;
        return $this;
    }
    public function getDescription(): ?string
    {
        return $this->description instanceof ConsentPurposeDescriptionVO ? $this->description->value() : $this->description;
    }
    public function isDescriptionAssigned(): bool
    {
        return $this->descriptionAssigned;
    }
    public function writeDescriptionTo(mixed $att): void
    {
        if ($this->descriptionAssigned) {
            \assert(null !== $this->description);
            $att->description($this->description);
        }
    }
    public function readDescriptionFrom(mixed $att): void
    {
        if ($att->isDescriptionAssigned()) {
            $description = $att->getDescription();
            \assert(null !== $description);
            $this->description($description);
        }
    }
    public function unsetDescription(): static
    {
        $this->descriptionAssigned = false;
        return $this;
    }
    protected function withDefaultDescription(): void
    {
    }
    protected function withAssertedDescriptionRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->descriptionAssigned = $this->descriptionAssigned) {
            $value->description = ConsentPurposeDescriptionVO::tryFrom($this->description, $errorsList);
        }
    }
}
